#pragma once#ifdef __MAIN_FILE__//UINT nMessageKeyboard = ::RegisterWindowMessageA("Внешняя Клавиатура");//char szClassNameCOM1[] =  "Keyboard COM1";BOOL IsKeyCOM1( HWND& hWnd )  {  static HWND gs_hWnd;  if ( !::IsWindow( gs_hWnd ) )  gs_hWnd = ::FindWindow(szClassNameCOM1,NULL);  hWnd = gs_hWnd;	return ::IsWindow(hWnd);  }//char szClassNameUSB[] =  "Keyboard USB";BOOL IsKeyUSB( HWND& hWnd )  {  static HWND gs_hWnd;  if ( !::IsWindow( gs_hWnd ) )  gs_hWnd = ::FindWindow(szClassNameUSB,NULL);  hWnd = gs_hWnd;	return ::IsWindow(hWnd);  }//char szClassNameHW[] =  "Keyboard Honeywell";BOOL IsKeyHW( HWND& hWnd )  {  static HWND gs_hWnd;  if ( !::IsWindow( gs_hWnd ) )  gs_hWnd = ::FindWindow(szClassNameHW,NULL);  hWnd = gs_hWnd;	return ::IsWindow(hWnd);  }//#else//extern UINT nMessageKeyboard;extern char szClassNameCOM1[];extern BOOL IsKeyCOM1( HWND& hWnd );extern char szClassNameUSB[];extern BOOL IsKeyUSB( HWND& hWnd );extern char szClassNameHW[];extern BOOL IsKeyHW( HWND& hWnd );//#endif#define  MessageCOM1( hWnd, wParam )  SendMessage( hWnd, nMessageKeyboard, wParam, 0 )#define  MessageUSB( hWnd, wParam )  SendMessage( hWnd, nMessageKeyboard, wParam, 0 )// Период мерцания#define INDICATOR_OFF       0x01 // Не горит#define INDICATOR_ON        0x02 // Горит постоянно#define INDICATOR_BLINKFAST 0x03 // Мерцает 500  ms#define INDICATOR_BLINKSLOW 0x04 // Мерцает 1000 ms// INDICATORS#define FAST_INDICATOR  0xFB#define ALPHA_INDICATOR 0xF7//#define KEY_DOWN_CODE			0x80	#define KEY_UP_CODE				0xf0//